// batch —— 批处理多个 set，合并触发
// ============================================================

let batchDepth = 0;
const pendingEffects = new Set<ReactiveEffect>();
let scheduled = false;

/**
 * 将多个修改合并到一个 flush：内部嵌套调用只累加 depth。
 * flush 默认同步执行，但在最外层用 queueMicrotask 避免嵌套。
 */
export function batch<T>(fn: () => T): T {
  batchDepth++;
  try {
    return fn();
  } finally {
    batchDepth--;
    if (batchDepth === 0) {
      flushBatch();
    }
  }
}

