    const lineEnd = buf.indexOf(CRLF_BUF, pos);
    if (lineEnd === -1) {
      return { body: Buffer.alloc(0), consumed: 0, complete: false };
    }
    const sizeLine = buf.subarray(pos, lineEnd).toString("ascii").trim();
