  return messages;
}
function serialize(msg) {
  const lines = [];
  if (msg.kind === "request") {
    lines.push(`${msg.method} ${msg.path} ${msg.version}`);
  } else {
    lines.push(`${msg.version} ${msg.statusCode} ${msg.reasonPhrase}`);
  }
  for (const [key, value] of Object.entries(msg.headers)) {
    lines.push(`${key}: ${value}`);
