class MyPromise {
  state = "pending";
  value;
  reason;
  callbacks = [];
  constructor(executor) {
    const resolve = (value) => {
      if (this.state !== "pending") return;
      if (value && typeof value.then === "function") {
        value.then(resolve, reject);
        return;
      }
      this.state = "fulfilled";
      this.value = value;
      this.flush();
    };
    const reject = (reason) => {
      if (this.state !== "pending") return;
      this.state = "rejected";
      this.reason = reason;
      this.flush();
    };
    try {
      executor(resolve, reject);
    } catch (e) {
      reject(e);
    }
  }
  // 用微任务模拟异步执行回调(真实 Promise 遵循同样的时机)
  flush() {
    queueMicrotask(() => {
      this.callbacks.forEach(({ ok, fail }) => {
        try {
          if (this.state === "fulfilled") ok(this.value);
          else fail(this.reason);
        } catch (e) {
          console.error("回调执行出错(教学版简化):", e);
        }
      });
      this.callbacks = [];
    });
  }
  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => {
      const handle = () => {
        try {
          if (this.state === "fulfilled") {
            resolve(onFulfilled ? onFulfilled(this.value) : this.value);
          } else {
            if (!onRejected) return reject(this.reason);
            resolve(onRejected(this.reason));
          }
        } catch (e) {
          reject(e);
        }
      };
      this.callbacks.push({ ok: handle, fail: handle });
      if (this.state !== "pending") this.flush();
    });
  }
  catch(onRejected) {
    return this.then(null, onRejected);
  }
  finally(cb) {
    return this.then(
      (v) => MyPromise.resolve(cb()).then(() => v),
      (e) => MyPromise.resolve(cb()).then(() => {
        throw e;
      })
    );
  }
  static resolve(value) {
    return new MyPromise((resolve) => resolve(value));
  }
  static reject(reason) {
    return new MyPromise((_, reject) => reject(reason));
  }
}
MyPromise.resolve(1).then((v) => v + 1).then((v) => MyPromise.resolve(v * 10)).then((v) => {
  console.log("链式结果:", v);
  throw new Error("手动抛错");
}).catch((e) => console.log("捕获:", e.message)).finally(() => console.log("finally 总是执行"));

