// ---- 嵌套对象:读取链上每一级都会被代理与收集 ----
const profile = reactive({ user: { name: 'Alice' } });
effect(() => {
    console.log('profile effect:', profile.user.name); // 依赖:user 与 user.name 两级
});
profile.user.name = 'Bob'; // → profile effect: Bob —— 深层修改自动触发

// ---- 验证:分支切换后的依赖清理 ----
