class History {
  // redo 栈
  constructor(state) {
    this.state = state;
  }
  past = [];
  future = [];
  /** 执行命令:清空 redo 栈(分叉后旧未来作废) */
  execute(cmd) {
    this.state = cmd.do(this.state);
    this.past.push(cmd);
    this.future = [];
    return this.state;
  }
  undo() {
    const cmd = this.past.pop();
    if (!cmd) return this.state;
    this.state = cmd.undo(this.state);
    this.future.unshift(cmd);
    return this.state;
  }
  redo() {
    const cmd = this.future.shift();
    if (!cmd) return this.state;
    this.state = cmd.do(this.state);
    this.past.push(cmd);
    return this.state;
  }
  get current() {
    return this.state;
  }
}
const addLine = (text) => ({
