  constructor() {
    super();
    this.peak = 0;
  }
  process(inputs) {
    const channel = inputs[0]?.[0];
    if (channel) {
      for (let i = 0; i < channel.length; i++) {
        const abs = Math.abs(channel[i]);
        if (abs > this.peak) this.peak = abs;
      }
      if (this.peak > 1e-3) this.port.postMessage({ level: this.peak });
      this.peak *= 0.95;
    }
    return true;
  }
}
