// 所有同源页面用相同频道名即可互通
const channel = new BroadcastChannel('app-channel');

// 接收
channel.onmessage = (e: MessageEvent) => {
    if (e.data.type === 'THEME_CHANGE') applyTheme(e.data.theme);
