class ResilientSocket {
  // 服务端据此去重与补发
  constructor(url, onMsg) {
    this.url = url;
    this.onMsg = onMsg;
    this.connect();
  }
  ws = null;
  attempts = 0;
  closedByUser = false;
  hbTimer;
  watchdogTimer;
  queue = [];
  // 未连接期间的发送队列
  lastSeq = 0;
  connect() {
    const ws = new WebSocket(this.url);
    this.ws = ws;
    ws.onopen = () => {
      this.attempts = 0;
      ws.send(JSON.stringify({ type: "resume", lastSeq: this.lastSeq }));
      this.queue.forEach((m) => ws.send(m));
      this.queue = [];
      this.startHeartbeat();
    };
    ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      if (msg.type === "pong") {
        this.feedWatchdog();
        return;
      }
      if (typeof msg.seq === "number") this.lastSeq = Math.max(this.lastSeq, msg.seq);
      this.onMsg(msg);
    };
    ws.onclose = () => {
      this.stopHeartbeat();
      if (!this.closedByUser) this.reconnect();
    };
    ws.onerror = () => ws.close();
  }
  // ① 应用层心跳：协议层 ping 在浏览器 API 里不可主动发，用业务消息 {"type":"ping"}
  startHeartbeat() {
    this.hbTimer = setInterval(() => {
      this.ws?.send(JSON.stringify({ type: "ping" }));
      this.watchdogTimer = setTimeout(() => this.ws?.close(), 8e3);
    }, 25e3);
  }
  feedWatchdog() {
    clearTimeout(this.watchdogTimer);
  }
  stopHeartbeat() {
    clearInterval(this.hbTimer);
    clearTimeout(this.watchdogTimer);
  }
  // ③ 全抖动指数退避：1s→2s→4s… 上限 30s，随机抖动防大量客户端同时重连打爆网关
  reconnect() {
    const delay = Math.min(3e4, 1e3 * 2 ** this.attempts) * (0.5 + Math.random() * 0.5);
    this.attempts++;
    setTimeout(() => this.connect(), delay);
  }
  send(msg) {
    const frame = JSON.stringify(msg);
    if (this.ws?.readyState === WebSocket.OPEN) {
      if (this.ws.bufferedAmount > 1e6) throw new Error("发送缓冲积压，背压保护");
      this.ws.send(frame);
    } else {
      this.queue.push(frame);
    }
  }
  close() {
    this.closedByUser = true;
    this.ws?.close();
    this.stopHeartbeat();
  }
}
export {
  ResilientSocket
};

